def normalized_matrix_tensor_product(P, T):
    if not P or not P[0] or not T or not T[0] or not T[0][0]:
        raise ValueError("Invalid input")
    m = len(P)
    l = len(P[0])
    l2 = len(T)
    a = len(T[0])
    b = len(T[0][0])
    if l != l2:
        raise ValueError("Invalid input")
    n = m * b
    R = [[0.0] * n for _ in range(a)]
    for i in range(m):
        for j in range(a):
            for k in range(b):
                s = 0.0
                for t in range(l):
                    s += P[i][t] * T[t][j][k]
                R[j][i * b + k] = s
    for c in range(n):
        col = [R[j][c] for j in range(a)]
        mean = sum(col) / a
        var = sum((x - mean) ** 2 for x in col) / a
        std = var ** 0.5
        for j in range(a):
            R[j][c] = 0.0 if std == 0 else (col[j] - mean) / std
    return R

