import numpy as np

def normalized_matrix_tensor_product(P, T):
    if not P or not P[0] or not T or not T[0] or not T[0][0]:
        raise ValueError("Invalid input")
    P = np.array(P, dtype=np.float64)
    T = np.array(T, dtype=np.float64)
    m, l = P.shape
    l2, a, b = T.shape
    if l != l2:
        raise ValueError("Invalid input")
    Q = np.einsum('it,tjk->ijk', P, T)
    R = Q.transpose(1, 0, 2).reshape(a, m * b)
    means = R.mean(axis=0)
    stds = R.std(axis=0, ddof=0)
    normalized = np.zeros_like(R)
    for col in range(R.shape[1]):
        if stds[col] != 0:
            normalized[:, col] = (R[:, col] - means[col]) / stds[col]
    return normalized.tolist()

