        float(s)
        return True
    except (ValueError, TypeError):
        return False

def _gammainc(a, x):
    if x <= 0 or a <= 0:
        return 0.0
    if x < a + 1.0:
        ap = a
        summ = 1.0 / a
        delt = summ
        for n in range(1, 1000):
            ap += 1
            delt *= x / ap
            summ += delt
            if abs(delt) < abs(summ) * 1e-15:
                break
        return summ * math.exp(-x + a * math.log(x) - math.lgamma(a))
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    for i in range(1, 1000):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delp = d * c
        h *= delp
        if abs(delp - 1.0) < 1e-15:
            break
